// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.providerimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — No-Op Local LLM Provider. * * Default [LocalLlmProvider] used by Hilt when no real model is loaded. * * Strategy §4.1: "The model file (ggml-*.bin) is stored in app internal storage * and loaded lazily on first use." Until the user downloads a model via * Settings → LLM → Model Manager, the brain uses this stub — it returns * `isLoaded=false` and `load()` fails with a clear message. The * [com.roshan.persona.brain.llm.layer.LocalLlmLayer] handles this gracefully * by returning `SkillOutput.Failure`, which causes the Brain's orchestrator * to defer to Layer 4 (CloudLlmLayer) or return an error to the UI. * * When :feature:llm's `LocalModelManager` loads a real model, it should * override this binding via: * * ```kotlin * @Module @InstallIn(SingletonComponent::class) * object RealLlmModule { *     @Provides @Singleton *     fun provideLocalLlmProvider(mgr: LocalModelManager): LocalLlmProvider = *         mgr.getCurrentProvider() ?: NoOpLocalLlmProvider() * } * ``` * * TODO: :feature:llm should provide the real binding once it ships. */@Singletonclass NoOpLocalLlmProvider @Inject constructor() : LocalLlmProvider {    override val modelId: String = "noop"    override val isLoaded: Boolean = false    override val contextLength: Int = 0    override val availableVramMb: Int = 0    override val modelSizeBytes: Long = 0L    override suspend fun load(): Result<Unit> = Result.Failure(        error = AppError.Llm.ModelMissing(            modelId = "noop",        ),        correlationId = CorrelationId.generate(),        durationNanos = 0,    )    override suspend fun unload(): Result<Unit> = Result.Success(        data = Unit,        correlationId = CorrelationId.generate(),        durationNanos = 0,    )    override suspend fun generate(        prompt: String,        config: GenerationConfig,        onToken: (String) -> Unit,    ): Result<GenerationResult> = Result.Failure(        error = AppError.Llm.ModelMissing(            modelId = "noop",        ),        correlationId = CorrelationId.generate(),        durationNanos = 0,    )    override suspend fun embed(text: String): Result<FloatArray> = Result.Failure(        error = AppError.Llm.ModelMissing(            modelId = "noop",        ),        correlationId = CorrelationId.generate(),        durationNanos = 0,    )}